  save('outer-launch-request.json', { time: new Date().toISOString(), executable: process.execPath, argv, env, cwd: '/private/tmp', runnerAttempts: 1, maximumSubjects: 3, maximumSupervisors: 3 });
  const output = { stdout: [], stderr: [] };
  const counts = { stdout: 0, stderr: 0 };
  let retainedBytes = 0;
  let spawnError;
