  try { save('outer-fatal.json', { time: new Date().toISOString(), reason: String(reason), stack: reason?.stack, childPid: child?.pid, childExitCode: child?.exitCode, childSignalCode: child?.signalCode, noRetry: true, noSignals: true }); }
