  process.exitCode = 1;
} finally {
  const closed = [];
  for (const entry of retained) {
    try { fs.closeSync(entry.handle); closed.push({ path: entry.path, closed: true }); }
    catch (reason) { closed.push({ path: entry.path, closed: false, reason: String(reason) }); process.exitCode = 1; }
  }
  try { save('outer-admission-cleanup.json', { time: new Date().toISOString(), handles: closed }); }
  catch (reason) { console.error('Outer admission cleanup publication failed', reason); process.exitCode = 1; }
}

